export const practiceDifficulties=["easy","standard","hard"],parseDifficulty=(t)=>practiceDifficulties.some((o)=>o===t)?t:"standard",practiceSlot=(t)=>t==="standard"?"practice":`practice:${t}`;export function practiceSettings(t,o){const i=document.createElement("div");i.className="practice-settings";i.hidden=!0;const s=document.createElement("div");s.className="practice-settings-row";const r=document.createElement("label");r.htmlFor="practice-difficulty";r.textContent="Difficulty";const e=document.createElement("select");e.id=r.htmlFor;e.setAttribute("aria-describedby","practice-difficulty-description");for(const c of practiceDifficulties){const a=document.createElement("option");a.value=c;a.textContent=c[0].toUpperCase()+c.slice(1);e.append(a)}const n=document.createElement("p");n.id="practice-difficulty-description";n.setAttribute("role","status");s.append(r,e);i.append(s,n);e.onchange=()=>o(parseDifficulty(e.value));return{element:i,sync(c,a){i.hidden=!a;e.value=c;n.textContent=t[c];n.hidden=!t[c]}}}